const MATURITY_STAGES=[
 {name:'Khởi động',range:'0 ≤ điểm < 25%',color:'#FFC8E2'},
 {name:'Bắt đầu',range:'25 ≤ điểm < 50%',color:'#FFE580'},
 {name:'Hình thành',range:'50 ≤ điểm < 75%',color:'#9BE8F5'},
 {name:'Nâng cao',range:'75 ≤ điểm < 100%',color:'#CCF586'},
 {name:'Dẫn dắt',range:'Điểm = 100%',color:'#D9C4FF'}
];
function maturityStage(score){return typeof score!=='number'||!Number.isFinite(score)||score<0||score>100?null:MATURITY_STAGES[score<25?0:score<50?1:score<75?2:score<100?3:4];}
function maturityTag(score){const stage=maturityStage(score);return stage?'<span class="maturity-tag" style="--stage:'+stage.color+'">'+stage.name+'</span>':'<span class="maturity-tag">Chưa đủ dữ liệu</span>';}
function maturityRules(){return card('Quy tắc xác định mức trưởng thành','Phân loại theo điểm gộp · dùng cùng ngưỡng cho tổng thể và từng trụ cột',
 '<div class="maturity-scale">'+MATURITY_STAGES.map((s,i)=>'<div style="--stage:'+s.color+'"><b>'+String(i+1).padStart(2,'0')+'</b><strong>'+s.name+'</strong><small>'+esc(s.range)+'</small></div>').join('')+'</div><div class="method-copy"><p>Điểm trụ cột = trung bình điểm quy đổi của các tiêu chí trong trụ cột. Điểm tổng thể = trung bình của 6 trụ cột, mỗi trụ cột trọng số 1/6. Phân loại trên điểm đầy đủ trước khi làm tròn.</p><p>Tên mức và ngưỡng phân loại theo phương pháp nghiên cứu của nhóm, áp dụng thống nhất cho tổng thể và từng trụ cột.</p><p>Điểm 0% có thể xuất phát từ mức 0 hoặc mức 1 của tiêu chí; không đồng nghĩa ngân hàng không có năng lực. Hồ sơ sử dụng dữ liệu gộp giai đoạn 2023–2025.</p></div>');}
function maturityProfile(){
 const bs=visible(),b=bank(S.bank==='all'?S.focus:S.bank)||bs[0],stage=maturityStage(b.score);
 const criteria=D.evidence.filter(e=>e.bank===b.name);
 const matrix='<div class="maturity-scroll"><table class="maturity-table"><caption class="sr-only">Mức trưởng thành theo điểm gộp 2023–2025 của '+bs.length+' ngân hàng</caption><thead><tr><th scope="col">NGÂN HÀNG</th><th scope="col">TỔNG THỂ</th>'+D.pillars.map(p=>'<th scope="col">'+esc(p)+'</th>').join('')+'</tr></thead><tbody>'+bs.map(bb=>'<tr><th scope="row">'+bname(bb)+'</th><td><b>'+fmt(bb.score)+'%</b>'+maturityTag(bb.score)+'</td>'+bb.pillars.map(v=>'<td><b>'+fmt(v)+'%</b>'+maturityTag(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
 const rows=D.pillars.map((p,i)=>{const v=b.pillars[i],s=maturityStage(v),es=criteria.filter(e=>e.pillar===i),zeros=es.filter(e=>e.level===0).length;return '<div class="maturity-pillar" style="--stage:'+s.color+'"><div><h3>'+esc(p)+'</h3><span>'+D.counts[i]+' tiêu chí · '+zeros+' mức 0 trong dataset gộp</span></div><div class="maturity-meter" aria-hidden="true"><span style="width:'+v+'%"></span></div><strong>'+fmt(v)+'%</strong>'+maturityTag(v)+'</div>';}).join('');
 return ''+card('Bản đồ trưởng thành số','Điểm % và mức phân loại · không phải chuỗi thời gian',matrix)+'<div class="maturity-section">'+
 '<div class="detail-select" role="group" aria-label="Chọn hồ sơ trưởng thành">'+D.banks.map(bb=>'<button class="bank-pill '+(bb===b?'active':'')+'" data-focus="'+esc(bb.name)+'" aria-pressed="'+(bb===b)+'">'+badge(bb)+esc(bb.label)+'</button>').join('')+'</div>'+ 
 '<section class="card maturity-summary" style="--stage:'+stage.color+'"><div><div class="eyebrow">HỒ SƠ ĐANG XEM · 2023–2025</div><h2>'+esc(b.label)+'</h2><p>140 tiêu chí · 6 trụ cột · Dữ liệu gộp 2023–2025</p></div><div class="maturity-total"><strong>'+countNumber(b.score,1)+'<small>%</small></strong>'+maturityTag(b.score)+'</div></section>'+card('Mức trưởng thành theo từng trụ cột','Điểm trụ cột dùng số tiêu chí riêng; điểm tổng thể dùng trọng số bằng nhau',rows)+'<div class="maturity-actions"><button class="button primary" data-evidence-bank="'+esc(b.name)+'">Đối chiếu 140 tiêu chí ↗</button><button class="button" data-page="dna" data-focus="'+esc(b.name)+'">Xem Digital DNA ↗</button></div></div>'+maturityRules();
}
function maturityCSV(){csvDownload([['Ngân hàng','Phạm vi dữ liệu','Loại điểm','Trụ cột','Số tiêu chí','Điểm (%) chưa làm tròn','Mức trưởng thành','Ngưỡng','Trạng thái'],...visible().flatMap(b=>[{name:'Tổng thể',score:b.score,count:140},...D.pillars.map((name,i)=>({name,score:b.pillars[i],count:D.counts[i]}))].map(p=>[b.label,'Gộp 2023–2025',p.name==='Tổng thể'?'Trung bình 6 trụ cột':'Trung bình tiêu chí',p.name,p.count,p.score,maturityStage(p.score)?.name??'Chưa đủ dữ liệu',maturityStage(p.score)?.range??'','Sơ bộ · Dữ liệu gộp 2023–2025']))],'DBI_Digital_Maturity_Profile.csv');}
